vector<int> pn;

void SieveOfEratosthenes(int n) 
{   bool prime[n+1]; 
    memset(prime, true, sizeof(prime)); 
  
    for (int p=2; p*p<=n; p++) 
    { 
        
        if (prime[p] == true) 
        { 
         
        for (int i=p*p; i<=n; i += p) 
                prime[i] = false; 
        } 
    } 
    for (int p=2; p<=n; p++) 
       if (prime[p]) 
         pn.pb(p);
} 
int fp(int a,int n)
{
	int ans=1;
	while(n>0)
	{
		bool lb=n&1;
		if(lb)
			ans=(ans*a);
		a=(a*a);
		n=n>>1;
	}
	return ans;
}
