float dp[3000][3000];
float pro(int n,float* p,int i,int noh,int nott)
{
	if(i>n)
		return 1.0;
	float ans=0;
	if(dp[i][noh]!=-1)
		return dp[i][noh];
	if(noh+(n-i)>nott+1)
	{
		ans=1.0;
		ans=(1.0-p[i])*pro(n,p,i+1,noh,nott+1);
	}
	float ans1=1.0;
   ans1=p[i]*pro(n,p,i+1,noh+1,nott);
   return dp[i][noh]=ans+ans1;
}
void solve()
{
	int n;
	cin>>n;
	float p[n+1];
	for (int i = 1; i < n+1; ++i)
	{
		/* code */
		cin>>p[i];
	}
	for (int i = 0; i < 3000; ++i)
	{
		/* code */
		for (int j = 0; j < 3000; ++j)
		{
			/* code */
			dp[i][j]=-1;
		}
	}
	cout<<ps(pro(n,p,1,0,0),10);
	
}
